<?php
session_start(); require_once __DIR__ . '/config.php'; require_login();
$pdo = db(); $statement = $pdo->prepare("SELECT s.*, t.code, t.name toilet_name, (SELECT COUNT(*) FROM session_photos p WHERE p.session_id=s.id AND p.phase='before') before_count, (SELECT COUNT(*) FROM session_photos p WHERE p.session_id=s.id AND p.phase='after') after_count FROM toilet_sessions s JOIN toilets t ON t.id=s.toilet_id WHERE s.user_id=? ORDER BY s.check_in_at DESC"); $statement->execute([user()['id']]); $history = $statement->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My history · ClearCheck</title><link rel="stylesheet" href="assets/style.css"><script defer src="assets/lightbox.js"></script></head><body><header class="topbar"><a class="brand" href="app.php"><span class="brand-mark">CC</span><span>ClearCheck</span></a><div class="top-actions"><span class="user-chip"><span class="avatar"><?= e(strtoupper(substr(user()['name'], 0, 1))) ?></span><?= e(user()['name']) ?></span><a class="text-link" href="change_password.php">Password</a><a class="text-link" href="logout.php">Sign out</a></div></header><main class="page"><div class="page-heading"><div><p class="eyebrow">Student workspace</p><h1>My visit history.</h1><p class="muted">Your complete record of check-ins, check-outs, comments, and camera evidence.</p></div><a class="button outline" href="app.php">← Back to toilets</a></div><section class="history-section"><div class="table-wrap"><table><thead><tr><th>Visit</th><th>Toilet</th><th>Check-in comment</th><th>Check-out comment</th><th>Evidence</th><th>State</th></tr></thead><tbody><?php foreach ($history as $item): ?><tr><td><strong><?= format_date($item['check_in_at']) ?></strong><small><?= format_time($item['check_in_at']) ?><?= $item['check_out_at'] ? ' → ' . format_time($item['check_out_at']) : '' ?></small></td><td><strong><?= e($item['code']) ?></strong><small><?= e($item['toilet_name']) ?></small></td><td><?= e($item['check_in_comment']) ?></td><td><?= $item['check_out_comment'] ? e($item['check_out_comment']) : '<span class="muted">Not checked out</span>' ?></td><td><span class="evidence"><span>Before <?= $item['before_count'] ?></span><span>After <?= $item['after_count'] ?></span></span><br><button type="button" class="text-link" data-view-photos="<?= $item['id'] ?>">View photos</button></td><td><span class="history-state <?= $item['status']==='completed' ? 'done' : 'live' ?>"><?= ucfirst($item['status']) ?></span></td></tr><?php endforeach; if (!$history): ?><tr><td colspan="6" class="muted">No visits recorded yet.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
